import { source, history, part, view, choice, truth, exercise, s, op, c, sample, before, construction } from "./authoring.mjs";
const section="Choosing and Checking a Model";
const learningCurveScene = {
  kind: "plot", caption: "Invented errors for illustration. The lower green line is training MSE; the upper red line is validation MSE. No model was fitted to produce these teaching values.",
  points: [[10,1,2],[50,2,2],[100,3,2],[10,9,3],[50,6,3],[100,4,3]],
  paths: [[[10,1],[50,2],[100,3]],[[10,9],[50,6],[100,4]]],
  xLabel: "Number of training examples", yLabel: "Mean squared error", bounds: [0,100,0,10],
};
const evaluationLessons = [
  {
    id:"baseline-predictions",title:"What Must a Model Improve On?",section,topic:"Establish a Fair Comparison",
    blurb:"A complicated predictor needs a simple comparison. Before fitting one, we can measure how well a rule that always predicts a training average performs on new observations.",
    openingTitle:"Would the Average Have Done Just as Well?",
    opening:["Botie has a new model for greenhouse temperature. Its error sounds small, but small compared with what? If a simple rule would do just as well, the extra complexity has not yet earned its place.","We will start with a deliberately limited predictor: use the average training temperature for every new observation. That gives us a baseline, a result the more elaborate method should improve under the same evaluation conditions."],
    prerequisites:[before("Held-Out Evaluation","held-out-evaluation")],
    history:history("A Prediction Needs a Reference for Comparison",[source("Scikit-learn: DummyRegressor baseline strategies","https://scikit-learn.org/stable/modules/generated/sklearn.dummy.DummyRegressor.html")],"Predictive modelling needs control comparisons. Without them, a score cannot show whether a method gained anything from its inputs beyond a simple summary of previous outcomes.","Modern evaluation libraries preserve this practice through baseline estimators that ignore input features and predict a training summary. This is not an invention claim for one library. Our invented greenhouse example uses the training mean to make the comparison explicit before introducing more capable predictors."),
    intuition:[view("Learn a single training reference","The baseline sees the training outcomes and no features. Its only fitted value is their mean.",[["Training temperatures",["10","14","18"]],["Reference",["14"]]]),view("Predict before inspecting the answers","Every held-out observation receives that same reference. The held-out answers do not change it.",[["Predictions",["14","14"]],["Held-out temperatures",["12","20"]]]),view("Measure the errors","The baseline overpredicts one observation and underpredicts the other. Squaring keeps their sizes from cancelling.",[["Errors",["2","-6"]],["Squared errors",["4","36"]]])],
    parts:[part("1. Choose a Baseline That Matches the Task","A regression baseline might predict a mean or median. A classification baseline might use the majority class. A forecast might repeat the latest observation or the matching season. The baseline should be simple but relevant.\n\nFor our temperature example we will use the mean, because we will score squared errors. Among constant predictions, the training mean minimises the sum of squared training errors.","Training mean = (10 + 14 + 18) / 3 = 14","This fitted constant ignores inputs such as sunlight and heating settings. It establishes what we can achieve before using those features."),part("2. Freeze the Rule Before Evaluating It","Apply the fitted constant to held-out observations. Do not replace it with the held-out mean. That would use information the predictor did not have when making those predictions.","Held-out predictions: [14, 14]\nHeld-out answers:     [12, 20]\nErrors:               [2, -6]","A baseline must obey the same information boundary as the model it is compared with."),part("3. Score Both Methods on the Same Observations","Mean squared error averages the squared differences between predictions and answers. We need the same units, same held-out examples, and same metric for a fair comparison.","Baseline MSE = (2² + (-6)²) / 2\n             = (4 + 36) / 2\n             = 20","A model with lower error on different examples has not yet won this comparison. Shared evaluation examples let us compare their mistakes directly."),part("4. Ask What an Improvement Actually Buys","A small reduction in average error may not justify greater latency, maintenance, or instability. Inspect which observations improve and which get worse. Repeat the evaluation when the dataset is small or the fitting procedure is variable.\n\nThe baseline is a reference, not a target that guarantees usefulness once beaten. A temperature predictor may still be unsuitable for a particular control decision even after improving its average score.",null,"The workshop builds the whole baseline evaluation from training outcomes and held-out answers. It must not learn its constant from the test branch.")],
    quiz:[choice("Which data determine the baseline's constant?",["The held-out answers","The training outcomes","The better model's predictions"],1,"The training mean is fitted before we evaluate new observations."),truth("Both methods should be scored on the same held-out observations.",true,"Otherwise the difficulty of the evaluation data is another changing factor."),truth("Beating a baseline guarantees the model is suitable for deployment.",false,"Usefulness also depends on the size and nature of the improvement, uncertainty, and application requirements.")],
    practice:[exercise("Can you calculate the baseline before comparing it?",["Fit the constant using the training temperatures. Print that constant and the held-out MSE, each with four decimals."],"import numpy as np\ntraining = np.array([10.,14.,18.])\ntest = np.array([12.,20.])\n# Fit the reference, then score it.\n","import numpy as np\ntraining = np.array([10.,14.,18.])\ntest = np.array([12.,20.])\nprediction = training.mean()\nprint(f'{prediction:.4f}')\nprint(f'{np.mean((prediction-test)**2):.4f}')","14.0000\n20.0000",["Take the mean of training, not test.","Subtract the held-out answers from the frozen constant, square, and average."]),exercise("Did these new predictions beat the baseline on the same observations?",["Use the same training mean. The new test temperatures are 11 and 19, and the model predicts 12 and 17.","Print the baseline MSE, model MSE, and baseline-minus-model improvement with four decimals."],"import numpy as np\ntraining = np.array([10.,14.,18.])\ntest = np.array([11.,19.])\nmodel = np.array([12.,17.])\n# Compare both predictions on test.\n","import numpy as np\ntraining = np.array([10.,14.,18.])\ntest = np.array([11.,19.])\nmodel = np.array([12.,17.])\nbaseline_error = np.mean((training.mean()-test)**2)\nmodel_error = np.mean((model-test)**2)\nprint(f'{baseline_error:.4f}')\nprint(f'{model_error:.4f}')\nprint(f'{baseline_error-model_error:.4f}')","17.0000\n2.5000\n14.5000",["Use the identical test array for both errors.","A positive baseline-minus-model difference means the model had lower MSE on this test."])],
    build:construction("Measure the greenhouse baseline","Botie needs a reference score before adding a more complicated temperature model. Fit one constant on training data and evaluate it on the held-out temperatures.","Compute the training mean, subtract the held-out answers, square the differences, and return their mean.",{training:"Training temperatures",test:"Held-out temperatures"},[sample("First evaluation",{training:[10,14,18],test:[12,20]},20),sample("Different held-out days",{training:[10,14,18],test:[11,19]},17),sample("Different training reference",{training:[2,4,6],test:[3,7]},5)],op("mean",op("square",op("subtract",op("mean",s("training")),s("test")))),"The training branch supplies the prediction. Only the scoring branch reads the held-out answers.","This baseline uses no input features. Its score is a comparison, not a guarantee of acceptable temperature prediction.")
  },
  {
    id:"learning-curves",title:"Would More Examples Help?",section,topic:"Establish a Fair Comparison",
    blurb:"Before collecting more data or choosing a more flexible model, we can examine how training and validation errors change as the training set grows.",
    openingTitle:"Should We Collect More Readings or Change the Rule?",
    opening:["Botie's temperature model makes errors on new days. We could collect more days, or choose a more flexible rule. Those changes address different problems, so it helps to inspect the behaviour we already have.","Fit the same kind of model using several training-set sizes and measure both training and validation error. The resulting learning curves show how the method responds to more examples. They provide evidence for a decision, not a promise about what the next batch will do."],
    prerequisites:[before("What Must a Model Improve On?","baseline-predictions")],
    history:history("Model Comparisons Depend on How Much Data We Have",[source("Perlich, Provost, and Simonoff: A Learning-Curve Analysis (2003)","https://www.jmlr.org/papers/volume4/perlich03a/perlich03a.pdf"),source("Scikit-learn: Learning curves","https://scikit-learn.org/stable/modules/learning_curve.html")],"A comparison at one dataset size can hide how two learning methods respond as more examples become available. A method that works well with few observations need not remain the best choice with many.","Perlich, Provost, and Simonoff's 2003 study compared tree induction and logistic regression through learning curves. Our supplied greenhouse errors are invented illustrations, not results from that study or a model trained in this widget. They let us inspect the interpretation before running larger fitting experiments."),
    intuition:[view("Fit with different numbers of examples","Each column refers to the same model family fitted with a different amount of training data.",[["Training examples",["10","50","100"]]]),view("Keep the two errors separate","Training error measures the fitted examples. Validation error measures examples excluded from fitting. These illustrative curves show the two quantities coming closer as the training set grows.",[],learningCurveScene),view("Watch the gap alongside the actual errors","The gap narrows here as more data arrive. A narrow gap alone would not be enough if both errors remained large.",[["Validation minus training",["8","4","1"]]])],
    parts:[part("1. Change the Training Size, Not Everything at Once","Choose several training sizes. At each size, fit the same procedure from scratch, including preprocessing. Evaluate the fitted model on its training subset and on data excluded from that fit.\n\nKeep the metric and validation design consistent. Repeat subsets or splits when possible so an unusually easy selection does not masquerade as a trend.",null,"A learning curve varies the amount of training data. A validation curve instead varies a model setting. The axes answer different questions."),part("2. Inspect Both Curves Before Summarising Them","Low training error with much larger validation error suggests the fitted rule depends heavily on details of the training sample. If the gap shrinks as data increase, collecting more comparable data may help.\n\nIf both errors stay high and close together, the current representation or model may be too limited, although noise, poor measurements, or distribution mismatch can produce similar symptoms.","At 10 examples: gap = 9 - 1 = 8\nAt 50 examples: gap = 6 - 2 = 4\nAt 100 examples: gap = 4 - 3 = 1","The supplied illustration shows a narrowing gap and improving validation error. It is not a universal shape that all models must follow."),part("3. Do Not Mistake a Small Gap for a Good Predictor","Subtracting the two errors measures their difference, not their absolute quality. Equal errors can both be unacceptable. Compare the validation score with the baseline and with the needs of the application.","Training MSE = 20\nValidation MSE = 20\nGap = 20 - 20 = 0","This gap is smaller than in the earlier illustration, yet the validation error is much worse. A single gap score cannot replace the two curves."),part("4. Use the Pattern to Choose the Next Experiment","A curve can suggest whether to investigate more data, better features, regularisation, or a different model family. Test that suggestion rather than treating the visual pattern as a diagnosis with certainty.\n\nThe workshop calculates gaps from supplied errors. In a real study, obtaining each error requires a complete fit and evaluation at that training size. We keep those measurements explicitly separate from the arithmetic that summarises them.",null,"Final test data should not guide repeated decisions about which model or dataset size to choose. Use validation data for those development decisions.")],
    quiz:[choice("What changes along a learning curve's horizontal axis?",["Training-set size","The final test answers","The meaning of the target"],0,"We examine how a fixed fitting procedure responds to different amounts of training data."),truth("A zero training-validation error gap guarantees a useful predictor.",false,"Both errors can be equally large. Their levels and the baseline still matter."),truth("The widget's supplied errors are measured results from a model being fitted on the page.",false,"They are explicitly invented illustrations. The widget calculates their gaps, not training runs.")],
    practice:[exercise("How much does the error gap narrow in this illustration?",["Print the validation-minus-training gaps as a list, then the reduction from the first gap to the last with one decimal place."],"import numpy as np\ntraining = np.array([1.,2.,3.])\nvalidation = np.array([9.,6.,4.])\n# Compare matching training sizes.\n","import numpy as np\ntraining = np.array([1.,2.,3.])\nvalidation = np.array([9.,6.,4.])\ngaps = validation-training\nprint(gaps.tolist())\nprint(f'{gaps[0]-gaps[-1]:.1f}')","[8.0, 4.0, 1.0]\n7.0",["Subtract corresponding entries, preserving training-size order.","A reduction in gap is the first gap minus the last."]),exercise("Can two nearly identical curves still have poor errors?",["These are another set of supplied illustrative errors, not new fitted measurements. Print the gaps and final validation error.","Round both to one decimal place."],"import numpy as np\ntraining = np.array([12.,12.5,13.])\nvalidation = np.array([14.,13.8,13.5])\n# Keep the gap and error level visible.\n","import numpy as np\ntraining = np.array([12.,12.5,13.])\nvalidation = np.array([14.,13.8,13.5])\nprint(np.round(validation-training,1).tolist())\nprint(f'{validation[-1]:.1f}')","[2.0, 1.3, 0.5]\n13.5",["The final gap is small, but inspect the final error as well.","Use the last validation entry for the second printed result."])],
    build:construction("Compare the two greenhouse error curves","Botie has training and validation errors for matching training sizes. We need to see their differences without confusing a narrow gap with low error.","Return validation error minus training error at every supplied training size, preserving the order.",{training:"Illustrative training errors",validation:"Illustrative validation errors"},[sample("Narrowing gap",{training:[1,2,3],validation:[9,6,4]},[8,4,1]),sample("High errors, small gap",{training:[12,12.5,13],validation:[14,13.8,13.5]},[2,1.3,0.5]),sample("Equal errors",{training:[20,20],validation:[20,20]},[0,0])],op("subtract",s("validation"),s("training")),"Each subtraction compares the same training size. Read these gaps beside the error levels before deciding what to try next.","These errors are supplied teaching illustrations. No model is fitted by this construction.")
  },
  {
    id:"decision-thresholds",title:"When Should a Probability Become an Action?",section,topic:"From a Score to a Decision",
    blurb:"A probability is evidence, not a complete instruction. We need to decide how likely a sensor failure must be before an inspection is worth its cost.",
    openingTitle:"Should We Inspect Every Sensor That Might Fail?",
    opening:["Botie's model assigns each greenhouse sensor a probability of failure. An inspection costs time, but missing a real failure also has a cost. A probability alone does not decide which action is preferable.","We need a rule connecting those probabilities to consequences. A threshold says how large the estimated probability must be before we act. The appropriate threshold depends on the decision we are making."],
    prerequisites:[before("Logistic Regression","logistic-regression"),before("When the Important Class Is Rare","class-imbalance")],
    history:history("Separating Statistical Evidence From a Decision",[source("Scikit-learn: Tuning a decision threshold","https://scikit-learn.org/stable/modules/classification_threshold.html")],"Prediction systems have long needed a second step between estimating an outcome and choosing an action. The same estimated risk can justify different actions when their consequences differ.","Current threshold-tuning documentation makes that separation explicit: estimating scores and selecting a cutoff are distinct tasks. Our invented sensor costs show one simple expected-cost rule. They are teaching units, not an estimate of real maintenance costs or a recommendation for an operational safety system."),
    intuition:[view("Start with probabilities","The model supplies evidence about failure, not an inspection decision.",[["Failure probability",["0.1","0.4","0.8"]]]),view("Supply the consequence assumptions","Here a false alarm costs one unit and a missed failure costs four. Correct decisions cost zero in this simplified table.",[["False alarm cost",["1"]],["Missed failure cost",["4"]]]),view("Choose the action with lower expected cost","Those assumptions give a cutoff of 0.2. The workshop includes the boundary as an inspect decision.",[["Inspect?",["0","1","1"]]])],
    parts:[part("1. Keep Probability and Action Separate","A probability describes an estimated frequency under similar circumstances. An action has consequences. Raising the threshold generally reduces positive decisions; lowering it generally increases them. Neither change requires retraining the score model.\n\nThe effect on false alarms and missed failures depends on the labelled data and the score ordering.",null,"A conventional cutoff of one half is a convention, not a universal statement about the best decision."),part("2. Write Down the Cost Table","We will simplify the decision to inspect or leave alone. Correct decisions have zero cost. Inspecting a healthy sensor is a false alarm with cost one. Leaving a failed sensor alone is a miss with cost four.\n\nFor a failure probability p, inspection incurs the false-alarm cost only when the sensor is healthy. Leaving it alone incurs the missed-failure cost only when it fails.","Expected inspection cost = (1 - p) × 1\nExpected leave-alone cost = p × 4","These expectations assume that the estimated probability is suitable for this population and that the stated cost table describes the decision. Real inspections can have costs even when they are correct, which changes the table."),part("3. Find Where the Preferred Action Changes","The two expected costs are equal at the cutoff. Above it, a missed failure becomes more expensive in expectation than a false alarm. We choose inspection at equality as our stated tie rule.","(1 - p) × 1 = p × 4\n1 = 5p\np = 0.2\nGeneral cutoff = false-alarm cost / (false-alarm cost + miss cost)","The rule uses the relative costs. A larger missed-failure cost lowers the cutoff under these assumptions."),part("4. Choose and Test the Rule Without Reusing Final Answers","A cost-derived rule still needs evaluation. If we tune a threshold to a validation metric, we must keep the final test separate. Choosing the best cutoff on the final test and reporting that same result gives an optimistic estimate.\n\nCalibration also matters: a score labelled as a probability must be credible for expected-cost arithmetic. A ranking alone can support threshold searches on validation data, but does not justify interpreting every score as a probability.",null,"The workshop builds the cost-derived cutoff and applies it. The Python practice also evaluates a changed cost assumption.")],
    quiz:[truth("One half is always the best probability cutoff.",false,"The preferred cutoff depends on consequences, objectives, and the evaluation setting."),choice("Under our simplified cost table, what happens when missed failures become more costly?",["The cutoff decreases","The cutoff always becomes one","The input probabilities must all be set to zero"],0,"A lower failure probability can justify inspection when missing a failure has a larger cost."),truth("We can change an action threshold without changing the supplied model probabilities.",true,"The threshold is the decision step after probability estimation.")],
    practice:[exercise("Which sensors should Botie inspect under the stated costs?",["Use false-alarm cost 1 and miss cost 4. Print the derived cutoff with four decimals and the integer inspection decisions.","Inspect when the probability reaches the cutoff."],"import numpy as np\np = np.array([.1,.4,.8])\nfalse_alarm = 1.\nmiss = 4.\n# Derive the cutoff and apply it.\n","import numpy as np\np = np.array([.1,.4,.8])\nfalse_alarm = 1.\nmiss = 4.\ncutoff = false_alarm/(false_alarm+miss)\nprint(f'{cutoff:.4f}')\nprint((p >= cutoff).astype(int).tolist())","0.2000\n[0, 1, 1]",["Use both costs in the denominator.","The tie convention requires greater-than-or-equal, not strict greater-than."]),exercise("What changes when false alarms become more expensive?",["Use false-alarm cost 3 and miss cost 2. For probabilities 0.2, 0.5, 0.6, and 0.9, print the cutoff and decisions in the same format."],"import numpy as np\np = np.array([.2,.5,.6,.9])\nfalse_alarm = 3.\nmiss = 2.\n# Recompute the rule from the new costs.\n","import numpy as np\np = np.array([.2,.5,.6,.9])\nfalse_alarm = 3.\nmiss = 2.\ncutoff = false_alarm/(false_alarm+miss)\nprint(f'{cutoff:.4f}')\nprint((p >= cutoff).astype(int).tolist())","0.6000\n[0, 0, 1, 1]",["The probabilities have not been recalibrated or refitted. Only the decision costs changed.","Include the probability exactly at the cutoff."])],
    build:construction("Turn failure probabilities into inspection decisions","Botie has failure probabilities and a simplified cost table. Correct decisions cost zero; false alarms and missed failures have the supplied costs.","Derive the cutoff as false-alarm cost divided by the sum of both costs. Return one or zero for each probability, inspecting at equality.",{probabilities:"Estimated failure probabilities",falseAlarm:"False-alarm cost",miss:"Missed-failure cost"},[sample("Misses cost more",{probabilities:[.1,.4,.8],falseAlarm:1,miss:4},[0,1,1]),sample("False alarms cost more",{probabilities:[.2,.5,.6,.9],falseAlarm:3,miss:2},[0,0,1,1]),sample("Equal costs",{probabilities:[.4,.5,.7],falseAlarm:2,miss:2},[0,1,1])],op("gate",s("probabilities"),op("divide",s("falseAlarm"),op("add",s("falseAlarm"),s("miss")))),"The costs determine a cutoff. The gate then turns each supplied probability into an action under that rule.","This assumes credible probabilities, nonnegative costs with a positive sum, and zero cost for correct decisions. Different cost tables require a different derivation.")
  },
  {
    id:"probability-calibration",title:"Does Eighty Percent Mean Eighty Percent?",section,topic:"From a Score to a Decision",
    blurb:"A model can rank failures well and still overstate its probabilities. We need to compare its confidence with what actually happens across similar predictions.",
    openingTitle:"Can We Trust the Number Beside the Prediction?",
    opening:["Suppose Botie's model gives a group of sensors an 80 percent chance of failure. If we saw many comparable predictions, we would expect failures in roughly eight out of ten cases. That interpretation is what gives the probability practical meaning.","Our small report has four such predictions, and only two sensors failed. That is evidence to inspect, not proof from four observations alone. We need to compare estimated probabilities with observed frequencies while keeping the sample size visible."],
    prerequisites:[before("When Should a Probability Become an Action?","decision-thresholds")],
    history:history("A Correct Choice Can Still Come With Misleading Confidence",[source("Guo and colleagues: On Calibration of Modern Neural Networks (2017)","https://proceedings.mlr.press/v70/guo17a.html"),source("Scikit-learn: Probability calibration","https://scikit-learn.org/stable/modules/calibration.html")],"As classifiers improved, a separate question remained: did the number attached to a prediction accurately describe its uncertainty? A model could choose the right class often while being too confident about individual choices.","Guo and colleagues' 2017 study examined this issue in modern neural networks and evaluated calibration methods, including temperature scaling. Our invented sensor group teaches how to inspect reliability before attempting a correction. It does not reproduce their experiments or establish that one adjustment works for every model."),
    intuition:[view("Group comparable probability estimates","All four estimates are 0.8, so their average also represents the group's stated confidence.",[["Failure probabilities",["0.8","0.8","0.8","0.8"]]]),view("Record what happened","One means a failure occurred. Zero means it did not.",[["Outcomes",["1","0","1","0"]]]),view("Compare probability with frequency","The observed fraction is below the predicted probability in this small group. We need more evidence to estimate reliability precisely.",[["Mean probability",["0.8"]],["Failure frequency",["0.5"]]])],
    parts:[part("1. Calibration Is About Repeated Predictions","We cannot judge an 80 percent prediction as wrong merely because one sensor stayed healthy. A probabilistic statement allows both outcomes. Calibration concerns the outcome frequencies among many comparable probability estimates.\n\nA useful reliability diagram groups predictions into probability ranges and compares each group's average probability with its observed positive fraction.",null,"Grouping trades detail for enough observations to estimate a frequency. Different bin choices can change the appearance, particularly with little data."),part("2. Calculate One Reliability Group","Our four sensors all received the same estimated probability. Their binary outcomes sum to the number of failures. Averaging those outcomes gives the group's observed frequency.","Mean predicted probability = (0.8 + 0.8 + 0.8 + 0.8) / 4 = 0.8\nObserved failure frequency = (1 + 0 + 1 + 0) / 4 = 0.5\nPredicted minus observed = 0.8 - 0.5 = 0.3","This group looks overconfident about failure. Four examples are too few to establish a precise long-run discrepancy, so the report must preserve its count."),part("3. Score the Probability Errors Too","The binary Brier score averages squared differences between probabilities and zero-or-one outcomes. Lower is better. It penalises confident wrong predictions strongly.","Squared errors: [0.04, 0.64, 0.04, 0.64]\nBrier score = (0.04 + 0.64 + 0.04 + 0.64) / 4 = 0.34","Brier score is not a pure calibration measure. It also reflects how usefully the model distinguishes different risks. Inspect reliability and predictive discrimination separately rather than collapsing both questions into one label."),part("4. Fit Corrections on Separate Data","A calibration method learns a mapping from scores to probability estimates. It needs labelled data excluded from the original model fit or an appropriate cross-validation procedure. Evaluate the corrected probabilities on data not used to fit that correction.\n\nA model can be calibrated overall while failing for a subgroup or after a population change. It can also predict the same base rate for everyone and be calibrated while offering little useful ranking.",null,"The workshop audits one group. It does not fit a calibrator or certify that four observations establish reliable probabilities.")],
    quiz:[truth("One healthy sensor disproves an 80 percent failure probability.",false,"The probability permits healthy outcomes. Calibration is assessed across comparable predictions."),choice("What is the observed failure frequency in our four-sensor group?",["0.8","0.5","0.34"],1,"Two of the four sensors failed. The value 0.8 is the stated probability, and 0.34 is the Brier score."),truth("A lower Brier score alone proves every subgroup is calibrated.",false,"Brier score mixes aspects of probability quality and does not certify every subgroup's reliability.")],
    practice:[exercise("Can you audit this group of confident predictions?",["Print mean predicted probability, observed failure frequency, and Brier score on separate lines with four decimals."],"import numpy as np\np = np.array([.8,.8,.8,.8])\ny = np.array([1.,0.,1.,0.])\n# Report confidence, frequency, and squared probability error.\n","import numpy as np\np = np.array([.8,.8,.8,.8])\ny = np.array([1.,0.,1.,0.])\nprint(f'{p.mean():.4f}')\nprint(f'{y.mean():.4f}')\nprint(f'{np.mean((p-y)**2):.4f}')","0.8000\n0.5000\n0.3400",["A binary outcome's average is the observed positive fraction.","The Brier score squares the error before averaging."]),exercise("What does a less confident group's report show?",["Repeat the same audit for four predictions of 0.25 and outcomes containing one failure.","Print the same three quantities with four decimals."],"import numpy as np\np = np.array([.25,.25,.25,.25])\ny = np.array([0.,1.,0.,0.])\n# Keep the report format unchanged.\n","import numpy as np\np = np.array([.25,.25,.25,.25])\ny = np.array([0.,1.,0.,0.])\nprint(f'{p.mean():.4f}')\nprint(f'{y.mean():.4f}')\nprint(f'{np.mean((p-y)**2):.4f}')","0.2500\n0.2500\n0.1875",["Agreement in this group does not mean every individual probability error is zero.","There is still one outcome of one and three outcomes of zero."])],
    build:construction("Audit one group of failure probabilities","Botie needs to compare the group's confidence with its observed failure rate, while also reporting squared probability error.","Return two entries: first a pair containing mean probability and observed failure frequency, then the Brier score. Outcomes are zero or one.",{probabilities:"Failure probabilities in one group",outcomes:"Observed failures"},[sample("Confident group",{probabilities:[.8,.8,.8,.8],outcomes:[1,0,1,0]},[[.8,.5],.34]),sample("Lower-risk group",{probabilities:[.25,.25,.25,.25],outcomes:[0,1,0,0]},[[.25,.25],.1875])],op("pack",op("pack",op("mean",s("probabilities")),op("mean",s("outcomes"))),op("mean",op("square",op("subtract",s("probabilities"),s("outcomes"))))),"The first pair compares probability with frequency. The separate score reports average squared error without pretending it measures calibration alone.","These tiny groups illustrate the arithmetic. They do not estimate calibration precisely or fit a correction.")
  },
  {
    id:"grouped-validation",title:"Have We Really Held Out a New Example?",section,topic:"Establish a Fair Comparison",
    blurb:"Several rows can belong to the same greenhouse, patient, or device. If we want to predict for a new entity, a random row split can put familiar entities on both sides of the evaluation.",
    openingTitle:"Was the Greenhouse New, or Just the Row?",
    opening:["Botie records several readings from each greenhouse. We want to know whether a model will work for a greenhouse it has never encountered. Randomly splitting individual readings can put one greenhouse's morning reading in training and its afternoon reading in validation.","Those are different rows, but they share the same greenhouse. The model may benefit from familiar construction, sensor behaviour, and location. To answer the new-greenhouse question, the whole greenhouse must stay on one side of the split."],
    prerequisites:[before("What Could We Know at Prediction Time?","data-leakage")],
    history:history("Repeated Measurements Need a Different Evaluation Boundary",[source("Scikit-learn: Cross-validation for grouped data","https://scikit-learn.org/stable/modules/cross_validation.html#cross-validation-iterators-for-grouped-data")],"Repeated observations are common in scientific datasets. Measurements from one person, device, or location can share properties that distinguish them from other groups. Treating all rows as independent can therefore overstate performance on new groups.","Grouped validation procedures address the evaluation boundary by keeping a group's observations together. Scikit-learn documents these splitters separately from ordinary random splits. Our invented greenhouses make the group identity visible without claiming that one split design is appropriate for every prediction task."),
    intuition:[view("Different rows can share an identity","Each greenhouse has several measurements. The group ID is attached to every row.",[["Record groups",["A","A","B","B","C","C"]]]),view("A row split can overlap groups","Different records from A and B appear on both sides, so neither greenhouse is truly unseen.",[["Training groups",["A","B"]],["Validation groups",["A","B","C"]]]),view("Hold out complete identities","Training on A and B while validating on C keeps the validation greenhouse unseen.",[["Training groups",["A","A","B","B"]],["Validation groups",["C","C"]]])],
    parts:[part("1. State What Must Be New","A new reading from a familiar greenhouse and a reading from a new greenhouse are different generalisation tasks. The split should reflect the one we intend to claim.\n\nFor a new-greenhouse evaluation, the greenhouse ID defines the group. For another task, the relevant group might be a patient, author, device, household, or location.",null,"Grouping is a modelling decision based on dependencies, not simply a request to split on whichever column is most convenient."),part("2. Keep All Records From a Held-Out Group Together","Choose held-out group identities, then select their rows. The remaining groups supply training rows. We should be able to list the group IDs on both sides and verify that their intersection is empty.","Training group IDs:   [A, A, B, B]\nValidation group IDs: [C, C]\nShared distinct groups: []\nOverlap count: 0","A zero overlap count is necessary for this grouping rule. It does not rule out other leakage, such as copies with different IDs or preprocessing fitted on all rows."),part("3. Weight the Report Deliberately","If one greenhouse contributes hundreds of rows and another contributes only a few, a pooled row score mostly describes the larger group. Depending on the goal, we may also want a score per greenhouse and an average across greenhouses.\n\nThose are different summaries. Report which one you used and keep group sizes visible. Do not call a group-average score a row-average score.",null,"The workshop audits identity overlap. It deliberately does not fit a model or choose how group errors should be weighted."),part("4. Combine Grouping With Time When Necessary","A future reading from a new greenhouse may require both a time boundary and a group boundary. Neither a random grouped split nor a simple chronological split automatically handles both.\n\nAlso check whether held-out groups contain the classes needed for evaluation. Very few groups make uncertainty difficult to estimate even if the row count is large.",null,"The Python challenges select held-out rows by group identity and audit a separate proposed split. That makes the evaluation design inspectable before any fitting happens.")],
    quiz:[truth("Different row numbers guarantee independent greenhouse identities.",false,"Several rows can belong to the same greenhouse and share its characteristics."),choice("For a new-greenhouse evaluation, what belongs entirely on one side of the split?",["Every individual numerical value","All rows from a greenhouse","Only the target column"],1,"Keeping the entity together prevents that same greenhouse from appearing in training and validation."),truth("Zero group overlap proves every other kind of leakage is absent.",false,"It checks one boundary. Timing, preprocessing, duplicate identities, and other dependencies still need attention.")],
    practice:[exercise("Can you hold out greenhouse C completely?",["Print training row indices followed by validation row indices. Hold out every row whose greenhouse ID is C.","Indices are zero-based."],"import numpy as np\ngroups = np.array(['A','A','B','B','C','C'])\n# Select groups before selecting their rows.\n","import numpy as np\ngroups = np.array(['A','A','B','B','C','C'])\nvalidation = groups == 'C'\nprint(np.flatnonzero(~validation).tolist())\nprint(np.flatnonzero(validation).tolist())","[0, 1, 2, 3]\n[4, 5]",["The same decision must apply to every occurrence of C.","np.flatnonzero returns the positions where a Boolean mask is true."]),exercise("Does this proposed split really hold out new greenhouses?",["Print the sorted distinct group IDs shared by training and validation, then their count.","Repeated records of one group count as one overlapping identity."],"import numpy as np\ntraining = np.array(['A','A','B','D'])\nvalidation = np.array(['B','C','D','D'])\n# Audit overlap between distinct group identities.\n","import numpy as np\ntraining = np.array(['A','A','B','D'])\nvalidation = np.array(['B','C','D','D'])\nshared = np.intersect1d(training,validation)\nprint(shared.tolist())\nprint(shared.size)","['B', 'D']\n2",["Work with distinct identities rather than every repeated row.","np.intersect1d returns the shared distinct values in sorted order."])],
    build:construction("Audit the held-out greenhouses","Botie needs to know whether any greenhouse appears on both sides of a proposed split. Repeated rows must not count the same overlapping greenhouse more than once.","Keep distinct IDs on each side, compare their memberships, and count the shared identities. Return zero only when there is no overlap.",{training:"Training greenhouse IDs",validation:"Validation greenhouse IDs"},[sample("A proper group holdout",{training:["A","A","B"],validation:["C","C"]},0),sample("Two shared groups",{training:["A","A","B","D"],validation:["B","C","D","D"]},2),sample("Repeated overlap",{training:["A","A"],validation:["A","A","A"]},1)],op("total",op("flatten",op("membership",op("unique",s("training")),op("unique",s("validation"))))),"Distinct IDs remove repeated records from the audit. Each remaining match identifies one greenhouse shared by both sets.","This checks the supplied group identity only. It cannot discover hidden relationships or incorrectly assigned IDs.")
  },
  {
    id:"distribution-shift",title:"What Changed After the Model Was Fitted?",section,topic:"Know the Limits of the Result",
    blurb:"A model tested on one mix of conditions may later face another. Comparing the incoming data with the reference data helps us notice changes without pretending that every change proves an accuracy failure.",
    openingTitle:"Are We Still Predicting for the Same Greenhouses?",
    opening:["Botie's model was developed when most records came from glass-roofed greenhouses. The site expands, and plastic roofs now dominate the incoming reports. Even if the model code never changes, the population it sees has changed.","We need to notice that change before assuming the old evaluation still describes current performance. First we will compare simple category proportions. Then we will distinguish a changed input mix from a measured decline in prediction quality."],
    prerequisites:[before("Categories Without an Invented Ranking","categorical-encoding"),before("Have We Really Held Out a New Example?","grouped-validation")],
    history:history("When Training and Use No Longer Share the Same Distribution",[source("Lipton, Wang, and Smola: Detecting and Correcting for Label Shift (2018)","https://proceedings.mlr.press/v80/lipton18a.html")],"A predictor's evaluation can stop describing its environment when the frequencies or relationships in incoming data change. Detecting that mismatch is a separate problem from fitting the original predictor.","Lipton, Wang, and Smola's 2018 work studies label shift, where class proportions change under specific assumptions, and methods for detecting and correcting it. Our roof-category comparison is a simpler input-distribution audit. It is not their correction algorithm and does not assume that every observed change is label shift."),
    intuition:[view("Keep category meanings aligned","Both reports use the order glass, plastic, mesh. Counts cannot be compared until that order agrees.",[["Reference counts",["80","20","0"]],["Current counts",["40","60","0"]]]),view("Compare shares, not just volumes","Dividing each report by its own total removes a change caused only by collecting more rows.",[["Reference shares",["0.8","0.2","0"]],["Current shares",["0.4","0.6","0"]]]),view("Measure how much share moved","The loss of share in glass is balanced by the gain in plastic. Counting both sides without adjustment would count the same movement twice.",[["Absolute changes",["0.4","0.4","0"]],["Total variation distance",["0.4"]]])],
    parts:[part("1. Compare Like Categories Over Clear Windows","Choose a reference period and a current period. Keep the category vocabulary and collection rules consistent. A changed logging system can look like a changed population, so check how each report was produced.\n\nCounts depend on how many observations were collected. Proportions describe the mix within each report.","Reference shares = [80, 20, 0] / 100 = [0.8, 0.2, 0]\nCurrent shares = [40, 60, 0] / 100 = [0.4, 0.6, 0]","Both totals must be positive. An empty report has no empirical category distribution to compare."),part("2. Measure the Movement in Share","For discrete distributions over the same categories, total variation distance is half the sum of absolute probability differences. It ranges from zero for identical distributions to one for distributions with disjoint support.","Absolute differences = [|0.4 - 0.8|, |0.6 - 0.2|, |0 - 0|]\n                     = [0.4, 0.4, 0]\nTotal variation = (0.4 + 0.4 + 0) / 2 = 0.4","We divide by two because moved share appears once as a loss and once as a gain. This is a descriptive distance between the supplied category distributions, not a hypothesis-test p-value."),part("3. Keep Different Kinds of Change Separate","Input shift concerns changed feature distributions. Label shift concerns changed outcome proportions under an assumption about class-conditional inputs. A changed relationship between inputs and outcomes is often called concept drift.\n\nOur category audit can see roof proportions change. It cannot establish whether the temperature relationship changed, whether accuracy fell, or which assumption about outcomes holds.",null,"A stable input histogram does not prove performance is stable either. Relationships or labels can change without a visible shift in this particular feature."),part("4. Connect the Alert to an Investigation","Inspect subgroup performance when labels become available, check collection changes, and compare against the intended deployment population. A monitoring distance is useful when it leads to a concrete investigation.\n\nThresholds for alerts should account for ordinary sampling variation, seasonality, and the cost of investigating. Do not automatically retrain because one small batch looks different.",null,"The workshop calculates a transparent category distance. Its labels and proportions stay visible so the number has an interpretation.")],
    quiz:[truth("Doubling every count while preserving category shares changes this total variation distance.",false,"Normalising each report by its own total leaves the same proportions."),choice("What does our roof-category distance establish?",["The model's accuracy fell by the same amount","The supplied input-category proportions changed","The labels satisfy a label-shift assumption"],1,"We compared roof proportions only. We did not measure prediction accuracy or establish a relationship involving labels."),truth("A stable histogram of this one feature guarantees a stable model.",false,"Other features, outcomes, or relationships can change while this histogram stays the same.")],
    practice:[exercise("How much roof share moved between the two reports?",["Normalise each count vector by its own total. Print both proportion lists and their total variation distance with four decimals."],"import numpy as np\nreference = np.array([80.,20.,0.])\ncurrent = np.array([40.,60.,0.])\n# Compare aligned category proportions.\n","import numpy as np\nreference = np.array([80.,20.,0.])\ncurrent = np.array([40.,60.,0.])\np = reference/reference.sum()\nq = current/current.sum()\nprint(p.tolist())\nprint(q.tolist())\nprint(f'{np.abs(q-p).sum()/2:.4f}')","[0.8, 0.2, 0.0]\n[0.4, 0.6, 0.0]\n0.4000",["Counts and proportions answer different questions.","Take absolute differences so losses do not cancel gains, then divide their sum by two."]),exercise("Does a larger report necessarily indicate a changed mix?",["The reference counts are 8, 2, and 0; the new counts are 80, 20, and 0. Print the distance with four decimals.","Then compare that same reference with counts 2, 3, and 5 and print the second distance."],"import numpy as np\nreference = np.array([8.,2.,0.])\nreports = [np.array([80.,20.,0.]),np.array([2.,3.,5.])]\n# Compare each report's proportions with the reference.\n","import numpy as np\nreference = np.array([8.,2.,0.])\nreports = [np.array([80.,20.,0.]),np.array([2.,3.,5.])]\np = reference/reference.sum()\nfor report in reports:\n    q = report/report.sum()\n    print(f'{np.abs(q-p).sum()/2:.4f}')","0.0000\n0.6000",["Normalise the reference once and each report separately.","A new nonzero category contributes to the difference, but its column must already be aligned."])],
    build:construction("Compare the greenhouse population mix","Botie needs to compare roof-category shares in a reference report and a new report. Both use the same category order.","Normalise each count vector by its own total, take absolute differences, add them, and divide by two.",{reference:"Reference category counts",current:"Current category counts"},[sample("Changed roof mix",{reference:[80,20,0],current:[40,60,0]},0.4),sample("Only volume changed",{reference:[8,2,0],current:[80,20,0]},0),sample("A growing third category",{reference:[8,2,0],current:[2,3,5]},0.6)],op("divide",op("total",op("absolute",op("subtract",op("divide",s("current"),op("total",s("current"))),op("divide",s("reference"),op("total",s("reference")))))),c(2)),"Normalisation removes volume differences. The remaining distance measures how the supplied category shares differ.","Both reports must have positive totals and aligned, nonnegative counts. This is a distribution audit, not a performance estimate or an automatic retraining rule.")
  },
  {
    id:"bootstrap-uncertainty",title:"How Much Does Our Estimate Depend on This Sample?",section,topic:"Know the Limits of the Result",
    blurb:"One average hides how it might change if different observations had been collected. Resampling the observed data gives us a way to study that dependence under explicit assumptions.",
    openingTitle:"Would Another Set of Readings Give the Same Average?",
    opening:["Botie estimates the average greenhouse temperature from a small collection of readings. The arithmetic gives one answer, but another collection could give a different one. We want some sense of how dependent the estimate is on the sample.","The bootstrap repeatedly samples from the observations we already have, with replacement, and recalculates the estimate. It treats the observed collection as a stand-in for the population we could sample again. That assumption is useful, but it is also a limitation."],
    prerequisites:[before("Can We Repeat the Same Experiment?","reproducible-sampling"),before("Have We Really Held Out a New Example?","grouped-validation")],
    history:history("Using Computation to Recreate the Act of Sampling",[source("Efron: Bootstrap Methods: Another Look at the Jackknife (1979)","https://doi.org/10.1214/aos/1176344552")],"Statisticians often need the uncertainty of an estimate even when a convenient formula is unavailable. Repeating the entire real-world data collection may be impractical.","Efron's 1979 bootstrap paper developed a computational approach based on resampling the observed data. Our invented greenhouse readings show how replacement and repeated estimates work. Three displayed resamples make the mechanism inspectable; they are far too few to justify a useful confidence interval."),
    intuition:[view("Start with the observed readings","We have three observations. Each bootstrap resample will also contain three entries.",[["Observed readings",["10","20","30"]]]),view("Sample with replacement","Repeated indices repeat an observation. Other observations can be absent from a particular resample.",[["First index draw",["0","0","2"]],["Second index draw",["1","1","1"]],["Third index draw",["0","2","2"]]]),view("Recalculate the estimate each time","The collection of estimates describes variation under the resampling procedure. It does not add independent greenhouse measurements.",[["Resample means",["16.6667","20","23.3333"]]])],
    parts:[part("1. Treat the Observed Sample as a Temporary Population","For an ordinary nonparametric bootstrap, draw as many observations as the original sample contains, with replacement. Each original observation has equal chance on each draw.\n\nReplacement is essential. Sampling every observation once without replacement would only reorder the same sample and leave its mean unchanged.","Original sample: [10, 20, 30]\nA valid resample: [10, 10, 30]\nAnother resample: [20, 20, 20]","Repeated values are repeated selections of the same observed value. They are not new sensor measurements."),part("2. Recompute the Complete Statistic","For each resample, repeat the statistic of interest. Here that statistic is the mean. For more complicated estimates, the required procedure can include refitting a model or preprocessing rather than merely resampling an already summarised number.","First mean = (10 + 10 + 30) / 3 ≈ 16.6667\nSecond mean = (20 + 20 + 20) / 3 = 20\nThird mean = (10 + 30 + 30) / 3 ≈ 23.3333","These three fixed examples explain the mechanism. A real bootstrap uses many random resamples and checks whether the summary is stable enough for its purpose."),part("3. Summarise Variation Without Overclaiming","The spread of bootstrap estimates can estimate a standard error under appropriate conditions. Their quantiles can support a percentile interval, although different interval methods have different assumptions and accuracy.\n\nDo not call the range of three hand-picked resample means a 95 percent confidence interval. Neither their number nor their selection supports that interpretation.",null,"A confidence interval is a property of a repeated-sampling procedure. It is not a guarantee that every future individual greenhouse reading lies inside it."),part("4. Resample the Independent Units","Ordinary row resampling assumes the observed rows are suitable independent sampling units. Consecutive readings from one greenhouse may be dependent. Group or block resampling can preserve some of that structure when justified.\n\nResampling also cannot repair a biased collection process or create examples of conditions absent from the original data. If every original reading came from one season, bootstrap copies do not supply evidence about another season.",null,"The workshop gathers one supplied resample and calculates its mean. Python then processes several recorded draws, making the distinction between a draw and its estimate explicit.")],
    quiz:[choice("Why is replacement needed when bootstrapping this mean?",["It forces every resample mean to be identical","It allows the sample composition to vary","It creates new independent physical measurements"],1,"Without replacement, a full-size draw only reorders the same observations, leaving their mean unchanged."),truth("The range of our three hand-picked means is a defensible 95 percent confidence interval.",false,"Three illustrative draws are not a sufficiently sampled bootstrap distribution, and they were selected to show the mechanism."),truth("Dependent readings may require resampling groups or blocks rather than individual rows.",true,"The resampling unit should reflect the dependence and sampling design.")],
    practice:[exercise("Can you reproduce the three illustrative resample means?",["Use the supplied index rows to gather readings. Print each resample mean as a list rounded to four decimals.","These are fixed teaching draws, not enough random draws to estimate an interval."],"import numpy as np\nreadings = np.array([10.,20.,30.])\nindices = np.array([[0,0,2],[1,1,1],[0,2,2]])\n# Gather each resample, then average its entries.\n","import numpy as np\nreadings = np.array([10.,20.,30.])\nindices = np.array([[0,0,2],[1,1,1],[0,2,2]])\nprint(np.round(readings[indices].mean(axis=1),4).tolist())","[16.6667, 20.0, 23.3333]",["Indexing with the matrix of positions gives one resample per row.","Reduce the within-resample axis, keeping one mean per row."]),exercise("How do the estimates change for another recorded sample?",["For readings 4, 8, 12, and 16, use the three supplied full-size index draws.","Print the original mean, then the list of resample means, all with four-decimal rounding where needed."],"import numpy as np\nreadings = np.array([4.,8.,12.,16.])\nindices = np.array([[0,0,1,3],[1,2,2,3],[0,1,2,3]])\n# Compare the original estimate with resample estimates.\n","import numpy as np\nreadings = np.array([4.,8.,12.,16.])\nindices = np.array([[0,0,1,3],[1,2,2,3],[0,1,2,3]])\nprint(f'{readings.mean():.4f}')\nprint(np.round(readings[indices].mean(axis=1),4).tolist())","10.0000\n[8.0, 12.0, 10.0]",["Each draw contains four positions, matching the original sample size.","The third draw happens to contain every observation once, so its mean matches the original."])],
    build:construction("Recalculate a resampled greenhouse mean","Botie has a recorded bootstrap draw. Retrieve its observations with replacement and calculate the estimate for that draw.","Gather the supplied positions from the original readings, including repeats, then calculate their mean.",{readings:"Original observations",indices:"Recorded bootstrap indices"},[sample("Repeated low reading",{readings:[10,20,30],indices:[0,0,2]},16.6666666667),sample("Repeated middle reading",{readings:[10,20,30],indices:[1,1,1]},20),sample("Repeated high reading",{readings:[10,20,30],indices:[0,2,2]},23.3333333333)],op("mean",op("gather",s("readings"),s("indices"))),"The resample changes which observed values contribute and how often. Recalculating the mean turns that changed composition into one estimate.","The construction receives a fixed draw and performs no random sampling. A few illustrative means are not a confidence interval.")
  }
];
export default evaluationLessons;
